SELECT t.id::text task_id,t.title task_title,tr.reference_kind,tr.reference,tr.title,tr.url,r.display_name repository FROM task_references tr JOIN tasks t ON t.id=tr.task_id LEFT JOIN phases ph ON ph.id=t.phase_id LEFT JOIN plans pl ON pl.id=ph.plan_id LEFT JOIN repositories r ON r.id=tr.repository_id WHERE t.project_id=$1 AND t.status<>'cancelled' AND ((t.phase_id IS NULL AND (t.source_document_id IS NULL OR EXISTS(SELECT 1 FROM plans src_plan WHERE src_plan.source_document_id=t.source_document_id AND src_plan.is_current))) OR pl.is_current) ORDER BY t.title,tr.reference_kind,tr.reference
